def eulerian_num(n, m):
    if n < 0 or m < 1:
        return 0
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            if j == 0:
                dp[i][j] = (i - 1) * dp[i-1][j]
            elif j == i:
                dp[i][j] = (i - 1) * dp[i-1][j-1]
            else:
                dp[i][j] = (i - 1) * (dp[i-1][j-1] + dp[i-1][j])
    return dp[n][m]

